static const char sh_post[] =
"in vec2 q;\n"
"out vec4 o;\n"
"layout(binding=0) uniform sampler2D A;\n"
"layout(binding=1) uniform sampler2D B;\n"
"layout(binding=2) uniform sampler2D X;\n"
"void main(){\n"
"#ifdef DOWN\n"
"o=texture(A,q);\n"
"#endif\n"
"#ifdef UP\n"
"o=texture(A,q)*.5;\n"
"#endif\n"
"#ifdef FINAL\n"
"vec3 c=texture(A,q).rgb+texture(B,q).rgb*.1;\n"
"o=vec4(c/(1.+c),1);\n"
"#endif\n"
"}\n"
"\n";
